const c=wb.getWorksheet('COLLECTION');
// aggregate every same-structure sheet by header name
const agg=new Map(); const num=v=>typeof v==='number'?v:0;
for (const s of wb.getWorksheets().getItems?.() ?? []) {
  if (s.getName().toUpperCase()==='COLLECTION') continue;
  const [h,...rows]=s.getUsedRange().getValues(); const ix=n=>h.indexOf(n);
  for (const r of rows) {
    if (r[ix('TY')]==null||r[ix('TY')]==='') continue;
    const k=r[ix('TY')]+'|'+r[ix('OR')];
    const a=agg.get(k)??{br:r[ix('BR')],ty:r[ix('TY')],or:r[ix('OR')],sale:0,ret:0};
    if(ix('SALE')>=0)a.sale+=num(r[ix('SALE')]); if(ix('RET')>=0)a.ret+=num(r[ix('RET')]);
    agg.set(k,a);
  }
}
log(JSON.stringify([...agg.values()]));
const out=[]; const seen=new Set(); let item=0;
for (const r of c.getRange('A2:D8').getValues()) { const k=r[2]+'|'+r[3]; seen.add(k); const a=agg.get(k); item=r[0]; out.push([r[0],r[1],r[2],r[3],a.sale,a.ret,a.sale-a.ret]); }
for (const [k,a] of agg) if(!seen.has(k)) out.push([++item,a.br,a.ty,a.or,a.sale,a.ret,a.sale-a.ret]);
log(JSON.stringify(out), out.length);
await c.getRange('A9:G9').copyFrom('A8:G8');
c.getRange('A2:G'+(out.length+1)).setValues(out);
const last=out.length+1;
c.getRange('E'+last+':E'+last).getStyle().setNumberFormat('0;\\-0;\\-');
const all=c.getRange('A1:G'+last);
all.getStyle().getFont().update?.({});
all.getStyle().setFont({family:'Calibri',size:11,weight:400});
c.getRange('A1:G1').getStyle().setAlignment({horizontal:'left'});
for (const col of ['A','E','F','G']) c.getRange(col+'2:'+col+last).getStyle().setAlignment({horizontal:'right'});
for (const col of ['B','C','D']) c.getRange(col+'2:'+col+last).getStyle().setAlignment({horizontal:'left'});
for (let i=2;i<=last;i++) for (const col of ['E','F','G']) { const cell=c.getRange(col+i); if(cell.getValue()<0) cell.getStyle().getFont().setColor('#FF0000'); }
c.getRange('A1:G9')

